head.script:
scwin.onpageload = function() {
    windowContainer1.createWindow("페이지1", "", "windowContainer_wframe_floatingLayer_WPFF-394_(WSQ-4031)_sub.xml", "page001", "P0001", "", "", "", "", "", "wframe", "");
};
scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#windowContainer1_subWindow0_wframe_floatingLayer11_headerHTML', 'drag-n-drop', {
        dx: 200,
        dy: 0
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'windowContainer1_subWindow0_wframe_floatingLayer11').style.top == '0px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
